package io.aetheris.orchestrator.memory;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import java.net.URI;import java.net.http.*;import java.time.*;import java.util.Map;

@Component
public class AdaptiveLocalEmbeddingAdapter implements EmbeddingAdapter {
    private static final int TARGET_DIMENSIONS=96;private final LocalHashEmbeddingAdapter fallback;private final ObjectMapper mapper;private final HttpClient client;private final boolean neuralEnabled;private final String baseUrl;private final String model;private final Duration timeout;private volatile EmbeddingRuntimeSnapshot last=new EmbeddingRuntimeSnapshot("adaptive-local-v2","local-hash","local-hash-v1",false,false,true,TARGET_DIMENSIONS,0,0,"No embedding request recorded yet",Instant.EPOCH);
    public AdaptiveLocalEmbeddingAdapter(LocalHashEmbeddingAdapter fallback,ObjectMapper mapper,@Value("${aetheris.embedding.local-neural-enabled:false}") boolean neuralEnabled,@Value("${aetheris.embedding.ollama-base-url:http://127.0.0.1:11434}") String baseUrl,@Value("${aetheris.embedding.ollama-model:nomic-embed-text}") String model,@Value("${aetheris.embedding.timeout-seconds:8}") long timeoutSeconds){this.fallback=fallback;this.mapper=mapper;this.neuralEnabled=neuralEnabled;this.baseUrl=baseUrl==null?"http://127.0.0.1:11434":baseUrl.replaceAll("/+$","");this.model=model==null||model.isBlank()?"nomic-embed-text":model.trim();this.timeout=Duration.ofSeconds(Math.max(1,Math.min(timeoutSeconds,30)));this.client=HttpClient.newBuilder().connectTimeout(this.timeout).build();}
    @Override public String id(){return "adaptive-local-v2";}@Override public int dimensions(){return TARGET_DIMENSIONS;}
    @Override public float[] embed(String text){long started=System.nanoTime(),before=usedHeap();if(!neuralEnabled){float[]v=fallback.embed(text);record("local-hash",false,false,true,elapsed(started),usedHeap()-before,"Neural embedding disabled by configuration; deterministic local fallback used");return v;}try{String body=mapper.writeValueAsString(Map.of("model",model,"input",text==null?"":text));HttpRequest request=HttpRequest.newBuilder(URI.create(baseUrl+"/api/embed")).timeout(timeout).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String> response=client.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()<200||response.statusCode()>=300)throw new IllegalStateException("Local embedding endpoint returned HTTP "+response.statusCode());JsonNode values=mapper.readTree(response.body()).path("embeddings").path(0);if(!values.isArray()||values.size()==0)throw new IllegalStateException("Local embedding response contained no vector");float[]raw=new float[values.size()];for(int i=0;i<values.size();i++)raw[i]=(float)values.get(i).asDouble();float[]projected=project(raw);record("ollama-local",true,true,false,elapsed(started),usedHeap()-before,"Local neural embedding succeeded and was projected to Stage 9 vector width");return projected;}catch(Exception ex){float[]v=fallback.embed(text);record("local-hash",true,false,true,elapsed(started),usedHeap()-before,"Local neural embedding unavailable; deterministic local fallback used: "+safe(ex.getMessage()));return v;}}
    public EmbeddingRuntimeSnapshot runtime(){return last;}private float[] project(float[]raw){float[]out=new float[TARGET_DIMENSIONS];for(int i=0;i<raw.length;i++)out[i%TARGET_DIMENSIONS]+=raw[i];double norm=0;for(float v:out)norm+=v*v;if(norm>0){float scale=(float)(1/Math.sqrt(norm));for(int i=0;i<out.length;i++)out[i]*=scale;}return out;}private void record(String backend,boolean attempted,boolean used,boolean fallbackUsed,long latency,long heapDelta,String detail){last=new EmbeddingRuntimeSnapshot(id(),backend,used?model:fallback.id(),attempted,used,fallbackUsed,TARGET_DIMENSIONS,latency,heapDelta,detail,Instant.now());}private long usedHeap(){Runtime r=Runtime.getRuntime();return r.totalMemory()-r.freeMemory();}private long elapsed(long started){return Math.max(0,(System.nanoTime()-started)/1_000_000L);}private String safe(String v){if(v==null)return"unknown error";return v.length()>240?v.substring(0,240):v;}
}
